void check(bool ok,const QString& reason){if(!ok)throw std::runtime_error(reason.toStdString());}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{
 CadDocument doc;auto sketch=SketchGeometry::addRectangle(SketchGeometry::newFeature(doc.authored()["documentId"].toString(),"XY"),{{"u1Mm",10},{"v1Mm",8},{"u2Mm",30},{"v2Mm",20}});const auto edges=sketch["parameters"].toObject()["entities"].toArray();QJsonArray ids;for(const auto& e:edges)ids.append(e.toObject()["id"]);
 for(const auto& d:QJsonArray{QJsonObject{{"kind","horizontal"},{"entityId",ids[0]},{"valueMm",20}},QJsonObject{{"kind","vertical"},{"entityId",ids[1]},{"valueMm",12}}}){const auto solved=SketchGeometry::addDimension(sketch,d.toObject());check(solved.ok,solved.error);sketch=solved.feature;}

 const auto original=sketch;const auto width=sketch["parameters"].toObject()["dimensions"].toArray().first().toObject().value("id");
 // An explicitly empty group ID is creation, with all creation guards intact.
 for(const auto& supplied:QJsonArray{QJsonObject{},QJsonObject{{"entityIds",QJsonArray{}}},QJsonObject{{"entityIds",QJsonArray{ids[0]}}},QJsonObject{{"entityIds",ids},{"deltaUMm",0},{"deltaVMm",0}}}){
  auto bad=supplied.toObject();bad["groupId"]="";if(!bad.contains("deltaUMm"))bad["deltaUMm"]=5;if(!bad.contains("deltaVMm"))bad["deltaVMm"]=-3;
  const auto result=SketchGeometry::retainedMove(original,bad);check(!result.ok && result.feature==original,"Empty groupId cannot bypass creation qualification");
 }
 for(const auto& supplied:QJsonArray{QJsonObject{{"deltaUMm",5},{"deltaVMm",-3}},QJsonObject{{"entityIds",QJsonArray{}},{"deltaUMm",5},{"deltaVMm",-3}}}){const auto result=SketchGeometry::retainedMove(original,supplied.toObject());check(!result.ok && result.feature==original,"Absent groupId/selection refuses safely");}
 const auto emptyIdCreation=SketchGeometry::retainedMove(original,{{"groupId",""},{"entityIds",ids},{"deltaUMm",5},{"deltaVMm",-3}});check(emptyIdCreation.ok,"Empty groupId with qualified nonzero selection is ordinary creation");
 bool helperRefused=false;try{SketchMove::create(original["parameters"].toObject(),{},5,-3,{});}catch(const std::exception&){helperRefused=true;}check(helperRefused,"Owner builder checks cardinality before first()");
 QJsonObject args{{"entityIds",ids},{"deltaUMm",5},{"deltaVMm",-3}};auto moved=SketchGeometry::retainedMove(sketch,args);check(moved.ok,moved.error);sketch=moved.feature;const auto group=sketch["parameters"].toObject()["moveGroups"].toArray().first().toObject();check(moved.diagnostics["dof"].toInt()==0,"Source anchor removes placement freedom without extra output variables");
 const auto profile=SketchGeometry::evaluateFeature(original).profiles[0].profileId;
 auto verify=[&](const QJsonObject& now,double du,double dv,double size){const auto p=now["parameters"].toObject(),g=p["moveGroups"].toArray().first().toObject();check(g["id"]==group["id"] && g["entityIds"]==group["entityIds"] && p["entities"]==original["parameters"].toObject()["entities"] && p["constraints"]==original["parameters"].toObject()["constraints"],"Stable source/profile topology");double minU=1e10,maxU=-1e10,minV=1e10,maxV=-1e10;for(const auto& value:p["points"].toArray()){const auto point=value.toObject();minU=std::min(minU,point["uMm"].toDouble());maxU=std::max(maxU,point["uMm"].toDouble());minV=std::min(minV,point["vMm"].toDouble());maxV=std::max(maxV,point["vMm"].toDouble());for(const auto& row:g["sourcePoints"].toArray()){const auto source=row.toObject();if(source["pointId"]==point["id"])check(std::abs(point["uMm"].toDouble()-source["uMm"].toDouble()-du)<1e-9 && std::abs(point["vMm"].toDouble()-source["vMm"].toDouble()-dv)<1e-9,"Exactly one derivation");}}check(std::abs(minU-(10+du))<1e-6 && std::abs(maxU-(10+size+du))<1e-6 && std::abs(minV-(8+dv))<1e-6 && std::abs(maxV-(20+dv))<1e-6,"Exact transformed bounds");check(SketchGeometry::evaluateFeature(now).profiles[0].profileId==profile,"Same profile identity");};
 verify(sketch,5,-3,20);for(int n=0;n<3;++n){const auto repeat=SketchGeometry::solveDraft(sketch);check(repeat.ok && repeat.feature==sketch,"Repeated solve is idempotent");}
 args["groupId"]=group["id"];args["deltaUMm"]=7;args["deltaVMm"]=-2;moved=SketchGeometry::retainedMove(sketch,args);check(moved.ok,moved.error);sketch=moved.feature;verify(sketch,7,-2,20);check(sketch["parameters"].toObject()["moveGroups"].toArray().first().toObject()["sourcePoints"]==group["sourcePoints"],"Replacement edit preserves pre-Move source");
 moved=SketchGeometry::updateDimension(sketch,{{"dimensionId",width},{"valueMm",24}});check(moved.ok,moved.error);sketch=moved.feature;verify(sketch,7,-2,24);for(int n=0;n<3;++n){const auto repeat=SketchGeometry::solveDraft(sketch);check(repeat.ok && repeat.feature==sketch,"Size edit is composed once");}
 auto zero=args;zero["deltaUMm"]=0;zero["deltaVMm"]=0;moved=SketchGeometry::retainedMove(sketch,zero);check(moved.ok,moved.error);verify(moved.feature,0,0,24);
 const auto vertex=sketch["parameters"].toObject()["points"].toArray().first().toObject().value("id");
 const auto drag=SketchGeometry::movePoint(sketch,{{"pointId",vertex},{"uMm",100},{"vMm",100}});check(!drag.ok && drag.feature==sketch,"Derived output drag refused");const auto atomic=SketchGeometry::translateProfile(sketch,{{"entityIds",ids},{"deltaUMm",1},{"deltaVMm",1}});check(!atomic.ok && atomic.feature==sketch,"Atomic output Move refused");
 const auto constraint=SketchGeometry::addConstraint(sketch,{{"type","parallel"},{"entityIds",QJsonArray{ids[0],ids[2]}}});check(!constraint.ok && constraint.feature==sketch,"New output constraint refused");const auto deleted=SketchGeometry::deleteEntities(sketch,QJsonArray{ids[0]},{});check(!deleted.ok && deleted.feature==sketch,"Owner Delete refused");
 const auto fixed=SketchGeometry::toggleFixed(sketch,{{"entityIds",QJsonArray{ids[0]}}});check(!fixed.ok && fixed.feature==sketch,"Output Fix refused");
 const auto construction=SketchGeometry::setConstruction(sketch,{{"entityIds",ids},{"construction",true}});check(!construction.ok && construction.feature==sketch,"Owned topology role edit refused");
 const auto extraDimension=SketchGeometry::addDimension(sketch,{{"kind","linear"},{"entityId",ids[2]},{"valueMm",24}});check(!extraDimension.ok && extraDimension.feature==sketch,"New output dimension refused");
 auto corrupt=sketch,p=sketch["parameters"].toObject();auto points=p["points"].toArray();auto point=points[0].toObject();point["uMm"]=point["uMm"].toDouble()+1;points[0]=point;p["points"]=points;corrupt["parameters"]=p;const auto rejected=SketchGeometry::solveDraft(corrupt);check(!rejected.ok,"Public invalid cache is refused, not rematerialized");QSet<QString> claimed;check(!SketchGeometry::validateParameters(p,claimed).isEmpty(),"Public parameter validation refuses cache tampering");
 auto connected=SketchGeometry::addStandalonePoint(original,{{"uMm",10},{"vMm",8}});check(connected.ok,connected.error);const auto anchor=connected.feature["parameters"].toObject()["entities"].toArray().last().toObject()["pointId"].toString();auto linked=SketchGeometry::addConstraint(connected.feature,{{"type","coincident"},{"pointIds",QJsonArray{original["parameters"].toObject()["points"].toArray().first().toObject()["id"],anchor}}});check(linked.ok,linked.error);const auto crossing=SketchGeometry::retainedMove(linked.feature,{{"entityIds",ids},{"deltaUMm",5},{"deltaVMm",-3}});check(!crossing.ok && crossing.feature==linked.feature,"External relation refuses atomically");
 check(doc.commit(SketchGeometry::replaceFeature(doc.authored(),sketch),"Retained Move").isEmpty(),"Commit");const auto authored=doc.authored();doc.history().undo();doc.history().redo();check(doc.authored()==authored,"Exact document history");QTemporaryDir dir;const auto path=dir.filePath("retained-move.alloy");check(doc.save(path).isEmpty(),"Save");CadDocument reopened;check(reopened.open(path).isEmpty() && reopened.authored()==authored,"Exact authored reopen");std::cout<<"RETAINED_SKETCH_MOVE_CORE_OK\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
